-- Folds the `people` collection into `users` (src/collections/Users).
--
-- Additive: the `people*` tables and the `people_id` relationship columns are kept so the
-- deployment that is live while this runs keeps working; a follow-up script drops them once the
-- new build is out. Safe to re-run (every step is idempotent or guarded).
--
-- DDL was generated by diffing a Payload schema push of the old and new collection config;
-- the data steps map each person onto a user:
--   * person linked to a user  -> profile fields copied onto that user
--   * person without a login   -> new user with no login email (username = slug, approval off)
-- and re-point post authorship (posts_rels / _posts_v_rels) from people ids to user ids.
BEGIN;

-- ---------------------------------------------------------------------------------------------
-- 0. Production duplicates (one human, two People rows). Keep the row linked to the login.
-- ---------------------------------------------------------------------------------------------
UPDATE posts_rels    SET people_id = 277 WHERE people_id = 265;
UPDATE _posts_v_rels SET people_id = 277 WHERE people_id = 265;
DELETE FROM people_numbers           WHERE parent_id  IN (265, 269);
DELETE FROM people_texts             WHERE parent_id  IN (265, 269);
DELETE FROM people_role_assignments  WHERE _parent_id IN (265, 269);
DELETE FROM people_socials           WHERE _parent_id IN (265, 269);
DELETE FROM people WHERE id IN (265, 269);
UPDATE people SET slug = 'seojin-lee' WHERE id = 280 AND slug = '-143';

-- ---------------------------------------------------------------------------------------------
-- 1. Schema: enums, new users columns, child tables, relationship columns
-- ---------------------------------------------------------------------------------------------
DO $$ BEGIN CREATE TYPE "public"."enum_users_member_type" AS ENUM ('user', 'alumni'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "public"."enum_users_role_assignments_role" AS ENUM ('executive', 'president'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "public"."enum_users_socials_platform" AS ENUM ('x', 'github', 'linkedin', 'orcid', 'website'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

ALTER TABLE "users" ALTER COLUMN "email" DROP NOT NULL;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "slug" varchar;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "username" varchar;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "contact_email" varchar;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "member_type" "public"."enum_users_member_type" DEFAULT 'user';
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "is_visible" boolean DEFAULT true;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "bio" varchar;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "is_author" boolean DEFAULT false;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "avatar_id" integer;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "legacy_people_id" integer; -- migration bookkeeping, dropped below

CREATE TABLE IF NOT EXISTS "users_numbers" ("id" serial PRIMARY KEY NOT NULL, "number" numeric, "order" integer NOT NULL, "parent_id" integer NOT NULL, "path" varchar NOT NULL);
CREATE TABLE IF NOT EXISTS "users_texts" ("id" serial PRIMARY KEY NOT NULL, "order" integer NOT NULL, "parent_id" integer NOT NULL, "path" varchar NOT NULL, "text" varchar);
CREATE TABLE IF NOT EXISTS "users_role_assignments" ("_order" integer NOT NULL, "_parent_id" integer NOT NULL, "id" varchar PRIMARY KEY NOT NULL, "year" numeric NOT NULL, "role" "public"."enum_users_role_assignments_role" NOT NULL);
CREATE TABLE IF NOT EXISTS "users_socials" ("_order" integer NOT NULL, "_parent_id" integer NOT NULL, "id" varchar PRIMARY KEY NOT NULL, "platform" "public"."enum_users_socials_platform" NOT NULL, "url" varchar NOT NULL, "label" varchar);

ALTER TABLE "posts_rels"     ADD COLUMN IF NOT EXISTS "users_id" integer;
ALTER TABLE "_posts_v_rels"  ADD COLUMN IF NOT EXISTS "users_id" integer;
ALTER TABLE "header_rels"    ADD COLUMN IF NOT EXISTS "users_id" integer;
ALTER TABLE "footer_rels"    ADD COLUMN IF NOT EXISTS "users_id" integer;
ALTER TABLE "redirects_rels" ADD COLUMN IF NOT EXISTS "users_id" integer;

DO $$ BEGIN ALTER TABLE "users" ADD CONSTRAINT "users_avatar_id_media_id_fk" FOREIGN KEY ("avatar_id") REFERENCES "public"."media"("id") ON DELETE set null ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "users_numbers" ADD CONSTRAINT "users_numbers_parent_fk" FOREIGN KEY ("parent_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "users_texts" ADD CONSTRAINT "users_texts_parent_fk" FOREIGN KEY ("parent_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "users_role_assignments" ADD CONSTRAINT "users_role_assignments_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "users_socials" ADD CONSTRAINT "users_socials_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "posts_rels" ADD CONSTRAINT "posts_rels_users_fk" FOREIGN KEY ("users_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "_posts_v_rels" ADD CONSTRAINT "_posts_v_rels_users_fk" FOREIGN KEY ("users_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "header_rels" ADD CONSTRAINT "header_rels_users_fk" FOREIGN KEY ("users_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "footer_rels" ADD CONSTRAINT "footer_rels_users_fk" FOREIGN KEY ("users_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "redirects_rels" ADD CONSTRAINT "redirects_rels_users_fk" FOREIGN KEY ("users_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE INDEX IF NOT EXISTS "users_avatar_idx" ON "users" USING btree ("avatar_id");
CREATE INDEX IF NOT EXISTS "users_contact_email_idx" ON "users" USING btree ("contact_email");
CREATE INDEX IF NOT EXISTS "users_is_author_idx" ON "users" USING btree ("is_author");
CREATE INDEX IF NOT EXISTS "users_is_visible_idx" ON "users" USING btree ("is_visible");
CREATE INDEX IF NOT EXISTS "users_numbers_number_idx" ON "users_numbers" USING btree ("number");
CREATE INDEX IF NOT EXISTS "users_numbers_order_parent_idx" ON "users_numbers" USING btree ("order", "parent_id");
CREATE INDEX IF NOT EXISTS "users_role_assignments_order_idx" ON "users_role_assignments" USING btree ("_order");
CREATE INDEX IF NOT EXISTS "users_role_assignments_parent_id_idx" ON "users_role_assignments" USING btree ("_parent_id");
CREATE INDEX IF NOT EXISTS "users_socials_order_idx" ON "users_socials" USING btree ("_order");
CREATE INDEX IF NOT EXISTS "users_socials_parent_id_idx" ON "users_socials" USING btree ("_parent_id");
CREATE INDEX IF NOT EXISTS "users_texts_order_parent" ON "users_texts" USING btree ("order", "parent_id");
CREATE INDEX IF NOT EXISTS "posts_rels_users_id_idx" ON "posts_rels" USING btree ("users_id");
CREATE INDEX IF NOT EXISTS "_posts_v_rels_users_id_idx" ON "_posts_v_rels" USING btree ("users_id");
CREATE INDEX IF NOT EXISTS "header_rels_users_id_idx" ON "header_rels" USING btree ("users_id");
CREATE INDEX IF NOT EXISTS "footer_rels_users_id_idx" ON "footer_rels" USING btree ("users_id");
CREATE INDEX IF NOT EXISTS "redirects_rels_users_id_idx" ON "redirects_rels" USING btree ("users_id");

-- ---------------------------------------------------------------------------------------------
-- 2. Data: people -> users
-- ---------------------------------------------------------------------------------------------
-- 2a. People linked to a login: copy the profile onto that user.
UPDATE users u SET
  legacy_people_id = p.id,
  name          = COALESCE(NULLIF(TRIM(p.name), ''), NULLIF(TRIM(u.name), ''), split_part(u.email, '@', 1)),
  slug          = COALESCE(u.slug, p.slug),
  contact_email = COALESCE(u.contact_email, LOWER(p.email)),
  member_type   = COALESCE(p.member_type::text, 'user')::"public"."enum_users_member_type",
  is_visible    = COALESCE(p.is_visible, true),
  bio           = COALESCE(u.bio, p.bio),
  is_author     = COALESCE(p.is_author, false),
  avatar_id     = COALESCE(u.avatar_id, p.avatar_id)
FROM people p
WHERE p.user_id = u.id;

-- 2b. People without a login: a user row with no login email. `username` = slug satisfies
--     Payload's "email or username" rule for auth collections.
INSERT INTO users (legacy_people_id, name, slug, username, contact_email, member_type, is_visible, bio, is_author, avatar_id,
                   role, roles, is_approved, email_verified, created_at, updated_at)
SELECT p.id,
       COALESCE(NULLIF(TRIM(p.name), ''), 'Member ' || p.id),
       p.slug,
       p.slug,
       LOWER(p.email),
       COALESCE(p.member_type::text, 'user')::"public"."enum_users_member_type",
       COALESCE(p.is_visible, true),
       p.bio,
       COALESCE(p.is_author, false),
       p.avatar_id,
       'user', 'user', false, false, p.created_at, p.updated_at
FROM people p
WHERE p.user_id IS NULL
  AND NOT EXISTS (SELECT 1 FROM users u WHERE u.legacy_people_id = p.id);

-- 2c. Login users that never had a People row: give them a slug too.
UPDATE users SET slug = LOWER(regexp_replace(TRIM(name), '[^A-Za-z0-9]+', '-', 'g'))
WHERE slug IS NULL AND NULLIF(TRIM(name), '') IS NOT NULL;
UPDATE users SET slug = 'member-' || id WHERE slug IS NULL;
-- De-duplicate slugs by appending the id to every row but the first.
UPDATE users u SET slug = u.slug || '-' || u.id
FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY slug ORDER BY id) AS rn FROM users) d
WHERE d.id = u.id AND d.rn > 1;
UPDATE users SET name = COALESCE(NULLIF(TRIM(name), ''), split_part(email, '@', 1), 'Member ' || id) WHERE NULLIF(TRIM(name), '') IS NULL;
ALTER TABLE "users" ALTER COLUMN "name" SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "users_slug_idx" ON "users" USING btree ("slug");
CREATE UNIQUE INDEX IF NOT EXISTS "users_username_idx" ON "users" USING btree ("username");

-- 2d. Child tables: years, research topics, role assignments, socials.
INSERT INTO users_numbers ("number", "order", parent_id, path)
SELECT n.number, n."order", u.id, n.path
FROM people_numbers n JOIN users u ON u.legacy_people_id = n.parent_id
WHERE NOT EXISTS (SELECT 1 FROM users_numbers x WHERE x.parent_id = u.id AND x.path = n.path);

INSERT INTO users_texts ("order", parent_id, path, text)
SELECT t."order", u.id, t.path, t.text
FROM people_texts t JOIN users u ON u.legacy_people_id = t.parent_id
WHERE NOT EXISTS (SELECT 1 FROM users_texts x WHERE x.parent_id = u.id AND x.path = t.path);

INSERT INTO users_role_assignments (_order, _parent_id, id, year, role)
SELECT r._order, u.id, r.id, r.year, r.role::text::"public"."enum_users_role_assignments_role"
FROM people_role_assignments r JOIN users u ON u.legacy_people_id = r._parent_id
ON CONFLICT (id) DO NOTHING;

INSERT INTO users_socials (_order, _parent_id, id, platform, url, label)
SELECT s._order, u.id, s.id, s.platform::text::"public"."enum_users_socials_platform", s.url, s.label
FROM people_socials s JOIN users u ON u.legacy_people_id = s._parent_id
ON CONFLICT (id) DO NOTHING;

-- 2e. Relationships that pointed at people now point at the users.
UPDATE posts_rels r     SET users_id = u.id FROM users u WHERE r.people_id = u.legacy_people_id AND r.users_id IS NULL;
UPDATE _posts_v_rels r  SET users_id = u.id FROM users u WHERE r.people_id = u.legacy_people_id AND r.users_id IS NULL;
UPDATE header_rels r    SET users_id = u.id FROM users u WHERE r.people_id = u.legacy_people_id AND r.users_id IS NULL;
UPDATE footer_rels r    SET users_id = u.id FROM users u WHERE r.people_id = u.legacy_people_id AND r.users_id IS NULL;
UPDATE redirects_rels r SET users_id = u.id FROM users u WHERE r.people_id = u.legacy_people_id AND r.users_id IS NULL;

ALTER TABLE "users" DROP COLUMN IF EXISTS "legacy_people_id";

COMMIT;
